const esc=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const page=(l,title,body,desc)=>`<!doctype html><html lang="${l}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | Joyagoo research guide</title><meta name="description" content="${esc(desc)}"><link rel="canonical" href="${siteOrigin}/${l}/"><style>${style}${layoutOverride}${grandOverride}${magazineOverride}${archiveOverride}${mobileContentOverride}${boutiqueOverride}${nebulaOverride}${processOverride}${fashionOverride}${iceGalleryOverride}${floatingProductOverride}${mobileDensityOverride}</style></head><body>${header(l)}<main>${body}</main>${footer(l)}</body></html>`;
function header(l){const t=langs[l],x=labels[l];let opts=Object.entries(langs).map(([k,v])=>`<option value="${k}">${v.name}</option>`).join('');const switchLocale=`const parts=location.pathname.split('/').filter(Boolean),known=['en','de','fr','es','it','pt','nl','pl'];if(known.includes(parts[0]))parts[0]=this.value;else parts.unshift(this.value);location.href='/'+parts.join('/')+(location.pathname.endsWith('/')?'/':'')+location.search+location.hash`;return `<header><div class="nav"><a class="brand" href="/${l}/" aria-label="Joyagoo research"><img src="/assets/joyagoo-logo.svg" alt="Joyagoo"></a><nav><a href="/${l}/">${t.home}</a><a href="/${l}/categories/">${t.cats}</a><a href="/${l}/product-details/">${x.product}</a><a href="/${l}/seo-articles/">${x.articles}</a><a href="/${l}/guides/how-to-order/">${t.how}</a><a href="/${l}/guides/qc-workflow/">${t.qc}</a><a href="/${l}/faq/">${t.faq}</a></nav><select class="lang" aria-label="Choose language" onchange="${switchLocale}">${opts.replace(`value="${l}"`,`value="${l}" selected`)}</select></div></header>`}
const footer=l=>`<footer><strong>Joyagoo research preview</strong><p>${langs[l].disclaimer}</p><p><a href="https://findspreadsheet.com/">FindSpreadsheet.com</a> · <a href="/${l}/guides/country-support/">${langs[l].countries}</a></p></footer>`;
const pathWrite=(p,s)=>{mkdirSync(dirname(join(out,p)),{recursive:true});writeFileSync(join(out,p),s)};
function home(l){const t=langs[l],x=labels[l];return page(l,t.hero,`<section class="hero"><div><span class="eyebrow">${t.tag}</span><h1>${t.hero}</h1><p>${t.intro}</p><form class="search" role="search" action="https://findspreadsheet.com/search.html" method="get" onsubmit="const q=this.elements.keywords.value.trim();if(!q)return false;location.href='https://findspreadsheet.com/search.html?keywords='+encodeURIComponent(q)+'&channelid=2';return false"><input name="keywords" required placeholder="${t.placeholder}"><input type="hidden" name="channelid" value="2"><button class="button" type="submit">${t.search}</button></form><a class="button" href="https://findspreadsheet.com/">${t.db}</a></div><div class="product-rail hero-products" aria-label="FindSpreadsheet products">${heroProducts.map(p=>productTile(p,t)).join('')}</div></section><section class="section grid"><article class="card"><span class="pill">${x.new}</span><h3>${x.product}</h3><p>${x.cardProduct}</p><a href="/${l}/product-details/">${x.product} →</a></article><article class="card"><span class="pill">${x.new}</span><h3>${x.articles}</h3><p>${x.cardArticles}</p><a href="/${l}/seo-articles/">${x.articles} →</a></article></section><section class="section"><span class="eyebrow">${x.articles}</span><h2>${x.featuredArticles}</h2><div class="grid">${articles[l].slice(0,3).map(a=>`<article class="card"><span class="pill">${x.articles}</span><h3>${a[1]}</h3><p>${a[2]}</p><a href="/${l}/seo-articles/${a[0]}/">${a[1]} →</a></article>`).join('')}</div></section><section class="section"><span class="eyebrow">${t.cats}</span><h2>10 research paths, 10 different checks</h2><div class="grid category-grid">${cats.map(c=>`<article class="card"><span class="pill">${t.logic}</span><h3>${c[1]}</h3><p>${c[3]}</p><a href="/${l}/categories/${c[0]}/">${t.view} →</a></article>`).join('')}</div></section><section class="section split"><div><span class="eyebrow">Verified platform workflow</span><h2>Use platform facts for the order stage</h2><p>Joyagoo’s public Help Center describes product-link search, product and domestic-shipping payment, warehouse QC photos, a return window after QC, storage, parcel submission and later international shipping. This guide separates those platform steps from independent product selection.</p><a class="button" href="/${l}/guides/how-to-order/">${t.how}</a></div><div class="case"><strong>${t.check}</strong><p>Do not treat a catalog photo or low item price as a final decision. Record the selected variant, measurements, QC questions, parcel restrictions and final shipping quote.</p></div></section>`,t.intro)}
const productCopy={
 en:['Product details: turn a listing into a checkable decision','A product title and a catalog image are only a starting point. Capture the exact variant, measurements, materials, seller images and category-specific questions before moving to payment or parcel planning.','What to record','Selected colour, size and quantity; seller size chart; listed material; price and domestic shipping shown separately; and the QC views that would change your decision.'],
 de:['Produktdetails: aus einem Listing eine prüfbare Entscheidung machen','Produkttitel und Katalogbild sind nur ein Anfang. Halte die genaue Variante, Maße, Materialien, Verkäuferbilder und kategoriespezifische Fragen fest, bevor du Zahlung oder Versand planst.','Was du notierst','Gewählte Farbe, Größe und Menge; Größentabelle; Material; Artikelpreis und Inlandversand getrennt; sowie die QC-Ansichten, die deine Entscheidung ändern würden.'],
 fr:['Détails produit : transformer une fiche en décision vérifiable','Le titre et la photo catalogue ne sont qu’un point de départ. Notez la variante exacte, les mesures, matières, images vendeur et questions QC propres à la catégorie avant le paiement ou le colis.','À consigner','Couleur, taille et quantité choisies ; tableau des tailles ; matière ; prix article et livraison intérieure séparés ; et vues QC qui peuvent modifier votre décision.'],
 es:['Detalles del producto: convierte una ficha en una decisión verificable','El título y la foto de catálogo son solo el inicio. Registra variante exacta, medidas, materiales, imágenes del vendedor y preguntas QC de la categoría antes de pagar o planificar el paquete.','Qué registrar','Color, talla y cantidad elegidos; tabla de tallas; material; precio del artículo y envío nacional por separado; y las vistas QC que cambiarían tu decisión.'],
 it:['Dettagli prodotto: trasforma una scheda in una scelta verificabile','Titolo e foto di catalogo sono solo l’inizio. Registra variante esatta, misure, materiali, immagini del venditore e domande QC della categoria prima di pagare o pianificare il pacco.','Cosa annotare','Colore, taglia e quantità scelti; tabella taglie; materiale; prezzo articolo e spedizione nazionale separati; e le viste QC che cambierebbero la scelta.'],
 pt:['Detalhes do produto: transforme uma ficha numa decisão verificável','O título e a foto de catálogo são apenas o início. Registe a variante exata, medidas, materiais, imagens do vendedor e perguntas QC da categoria antes de pagar ou planear a encomenda.','O que registar','Cor, tamanho e quantidade escolhidos; tabela de medidas; material; preço do artigo e envio doméstico separados; e as vistas QC que mudariam a decisão.'],
 nl:['Productdetails: maak van een listing een controleerbare keuze','Een producttitel en catalogusfoto zijn slechts het begin. Leg de exacte variant, maten, materialen, verkopersfoto’s en categoriegerichte QC-vragen vast vóór betaling of pakketplanning.','Wat je vastlegt','Gekozen kleur, maat en aantal; maattabel; materiaal; artikelprijs en binnenlandse verzending apart; en de QC-aanzichten die je beslissing zouden veranderen.'],
 pl:['Szczegóły produktu: zamień ofertę w sprawdzalną decyzję','Tytuł produktu i zdjęcie katalogowe to dopiero początek. Zapisz dokładny wariant, wymiary, materiały, zdjęcia sprzedawcy i pytania QC dla kategorii przed płatnością lub planowaniem paczki.','Co zapisać','Wybrany kolor, rozmiar i ilość; tabela rozmiarów; materiał; cena produktu i wysyłka krajowa osobno; oraz ujęcia QC, które mogłyby zmienić decyzję.']
};
