function homeV7(l){const t=langs[l],x=labels[l],v=studioCopy[l];return page(l,t.hero,`<section class="neo-hero"><div class="neo-copy"><span class="neo-label">${v.kicker}</span><h1>${v.heading}</h1><p>${v.intro}</p><form class="neo-search" role="search" action="https://findspreadsheet.com/search.html" method="get" onsubmit="const q=this.elements.keywords.value.trim();if(!q)return false;location.href='https://findspreadsheet.com/search.html?keywords='+encodeURIComponent(q)+'&channelid=2';return false"><input name="keywords" required placeholder="${t.placeholder}"><input type="hidden" name="channelid" value="2"><button class="button" type="submit">${t.search}</button><a class="database-link" href="https://findspreadsheet.com/">${t.db}</a></form><div class="neo-microcopy">${v.s1} · ${v.s2} · ${v.s3}</div></div><div class="neo-scene" aria-label="${v.routes}"><article class="neo-panel one"><i class="panel-number">01</i><b>${v.s1}</b><span>${t.placeholder}</span></article><article class="neo-panel two"><i class="panel-number">02</i><b>${x.product}</b><span>${v.s2}</span></article><article class="neo-panel three"><i class="panel-number">03</i><b>${x.articles}</b><span>${v.s3}</span></article></div><div class="motion-products" aria-hidden="true"><img class="motion-product motion-coat" src="/assets/joyagoo-hero-second-composition.jpg" alt=""><img class="motion-product motion-bag" src="/assets/joyagoo-hero-second-composition.jpg" alt=""><img class="motion-product motion-sneaker" src="/assets/joyagoo-hero-second-composition.jpg" alt=""></div></section><section class="neo-route-deck"><a class="neo-route" href="/${l}/product-details/"><span>01 / ${v.routes}</span><h2>${x.product}</h2><p>${x.cardProduct}</p><b>${x.product} →</b></a><a class="neo-route" href="/${l}/seo-articles/"><span>02 / ${v.routes}</span><h2>${x.articles}</h2><p>${x.cardArticles}</p><b>${x.articles} →</b></a></section><section class="neo-category-section"><div class="neo-section-head"><div><span class="neo-section-label">${t.cats}</span><h2>${v.catsTitle}</h2></div><p>${v.catsText}</p></div><ol class="neo-category-grid">${cats.map((c,i)=>`<li><a href="https://findspreadsheet.com${c[2]}"><span>${String(i+1).padStart(2,'0')}</span><strong>${c[1]}</strong><em>→</em></a></li>`).join('')}</ol></section><section class="neo-reading"><div class="neo-section-head"><div><span class="neo-section-label">${v.reading}</span><h2>${x.featuredArticles}</h2></div><p>${v.intro}</p></div><nav class="neo-reading-list" aria-label="${x.articles}">${articles[l].slice(0,3).map((a,i)=>`<a href="/${l}/seo-articles/${a[0]}/"><span>${String(i+1).padStart(2,'0')}</span><h3>${a[1]}</h3><b>→</b></a>`).join('')}</nav></section><section class="neo-close"><div><span class="neo-label">JOYAGOO / RESEARCH</span><h2>${v.closing}</h2></div><div><p>${v.closingText}</p><a class="button" href="/${l}/guides/how-to-order/">${t.how}</a></div></section>`,v.intro)}
home=homeV7;
const homeFlow={
 en:{title:'How it works, from search to a clear next step',intro:'Start with a working product link or a search term. Choose size, colour and quantity before you move forward, then use product photos and QC questions to keep the selected variation clear.',factTitle:'Platform fact',fact:'Account actions, payment, order status, warehouse work, parcel submission and shipping choices happen on the relevant service. This research guide does not process them.',actionTitle:'Independent action',action:'Use this page to record your chosen variation, compare category-specific QC checks and open the product database only when you are ready.'},
 de:{title:'So funktioniert es: von der Suche zum klaren nächsten Schritt',intro:'Beginne mit einem Produktlink oder Suchbegriff. Wähle Größe, Farbe und Menge, bevor du weitergehst, und halte die gewählte Variante mit Fotos und QC-Fragen eindeutig fest.',factTitle:'Plattform-Fakt',fact:'Kontoaktionen, Zahlung, Bestellstatus, Lagerarbeit, Paketeinreichung und Versandoptionen erfolgen beim jeweiligen Service. Dieser Recherche-Guide verarbeitet sie nicht.',actionTitle:'Unabhängiger Schritt',action:'Nutze diese Seite, um die gewählte Variante festzuhalten, QC-Prüfungen je Kategorie zu vergleichen und die Produktdatenbank erst dann zu öffnen, wenn du bereit bist.'},
 fr:{title:'Comment cela fonctionne : de la recherche à la prochaine étape',intro:'Partez d’un lien produit ou d’un terme de recherche. Choisissez taille, couleur et quantité avant d’avancer, puis utilisez les photos et les questions QC pour garder la variante choisie claire.',factTitle:'Fait de plateforme',fact:'Les actions de compte, le paiement, le statut de commande, l’entrepôt, l’envoi de colis et les choix de livraison relèvent du service concerné. Ce guide ne les traite pas.',actionTitle:'Action indépendante',action:'Utilisez cette page pour noter la variante choisie, comparer les contrôles QC de chaque catégorie et ouvrir la base produit seulement quand vous êtes prêt.'},
 es:{title:'Cómo funciona: de la búsqueda al siguiente paso claro',intro:'Empieza con un enlace de producto o un término de búsqueda. Elige talla, color y cantidad antes de avanzar y usa fotos y preguntas de QC para mantener clara la variante seleccionada.',factTitle:'Dato de plataforma',fact:'Las acciones de cuenta, pagos, estado de pedido, almacén, envío de paquete y opciones de entrega ocurren en el servicio correspondiente. Esta guía no los procesa.',actionTitle:'Acción independiente',action:'Usa esta página para registrar la variante elegida, comparar controles de QC por categoría y abrir la base de productos solo cuando estés listo.'},
 it:{title:'Come funziona: dalla ricerca al prossimo passo chiaro',intro:'Parti da un link prodotto o da un termine di ricerca. Scegli taglia, colore e quantità prima di proseguire e usa foto e domande QC per tenere chiara la variante scelta.',factTitle:'Fatto della piattaforma',fact:'Azioni dell’account, pagamento, stato dell’ordine, magazzino, invio del pacco e opzioni di spedizione avvengono nel servizio pertinente. Questa guida non li gestisce.',actionTitle:'Azione indipendente',action:'Usa questa pagina per annotare la variante scelta, confrontare i controlli QC per categoria e aprire il database prodotti solo quando sei pronto.'},
 pt:{title:'Como funciona: da pesquisa ao próximo passo claro',intro:'Comece com um link de produto ou termo de pesquisa. Escolha tamanho, cor e quantidade antes de avançar e use fotos e perguntas de QC para manter clara a variante selecionada.',factTitle:'Fato da plataforma',fact:'Ações de conta, pagamento, estado do pedido, armazém, envio de encomenda e opções de entrega acontecem no serviço relevante. Este guia não os processa.',actionTitle:'Ação independente',action:'Use esta página para registar a variante escolhida, comparar verificações de QC por categoria e abrir a base de produtos apenas quando estiver pronto.'},
 nl:{title:'Zo werkt het: van zoeken naar een duidelijke volgende stap',intro:'Begin met een productlink of zoekterm. Kies maat, kleur en aantal voordat je verdergaat en gebruik foto’s en QC-vragen om de gekozen variant duidelijk vast te leggen.',factTitle:'Platformfeit',fact:'Accountacties, betaling, bestelstatus, magazijnwerk, pakketindiening en verzendkeuzes vinden plaats bij de betreffende service. Deze onderzoeksgids verwerkt ze niet.',actionTitle:'Onafhankelijke actie',action:'Gebruik deze pagina om de gekozen variant vast te leggen, QC-controles per categorie te vergelijken en de productdatabase pas te openen wanneer je klaar bent.'},
 pl:{title:'Jak to działa: od wyszukiwania do jasnego kolejnego kroku',intro:'Zacznij od linku do produktu lub hasła wyszukiwania. Wybierz rozmiar, kolor i ilość przed przejściem dalej, a następnie użyj zdjęć i pytań QC, by jasno zapisać wybrany wariant.',factTitle:'Fakt platformy',fact:'Działania na koncie, płatność, status zamówienia, magazyn, zgłoszenie paczki i wybór dostawy odbywają się w odpowiedniej usłudze. Ten przewodnik ich nie realizuje.',actionTitle:'Niezależne działanie',action:'Użyj tej strony, aby zapisać wybrany wariant, porównać kontrole QC dla kategorii i otworzyć bazę produktów dopiero, gdy będziesz gotowy.'}
};
