function homeV8(l){const t=langs[l],f=homeFlow[l];return homeV7(l).replace(`<a class="button" href="/${l}/guides/how-to-order/">${t.how}</a>`,`<a class="button" href="https://findspreadsheet.com/">${t.db}</a>`).replace(`</section></main>`,`</section><section class="neo-process"><div class="neo-process-head"><span class="neo-section-label">${t.how}</span><h2>${f.title}</h2><p>${f.intro}</p></div><div class="neo-process-grid"><article><span>01</span><h3>${f.factTitle}</h3><p>${f.fact}</p></article><article><span>02</span><h3>${f.actionTitle}</h3><p>${f.action}</p></article><article><span>03</span><h3>${t.countries}</h3><p>${t.countryText}</p></article></div></section></main>`)}
const iceGalleryOverride=`:root{--ink:#102746;--muted:#58708d;--paper:#f3f7fc;--accent:#234f87;--line:#d5e1ee;--glass:#ffffffc9}body{background:radial-gradient(circle at 8% 8%,#fff 0,transparent 24rem),radial-gradient(circle at 95% 25%,#dbeeff 0,transparent 30rem),linear-gradient(145deg,#f7fbff,#e7f0fa);color:var(--ink)}header{background:#fafdffdf;border-color:#d6e2ef;backdrop-filter:blur(18px)}nav a{color:#183555}.lang{background:#fafdff;border-color:#cbdcea;color:#183555}.button{background:linear-gradient(135deg,#102e55,#2866a5);box-shadow:0 12px 26px #12385c35}.button:hover{background:linear-gradient(135deg,#1d5e9e,#12335c);box-shadow:0 18px 34px #12385c42}.neo-hero{min-height:645px;background-image:linear-gradient(90deg,#0a2344 0%,#0a2344 44%,rgba(10,35,68,.92) 47%,rgba(10,35,68,.18) 54%,rgba(10,35,68,0) 62%),url('/assets/joyagoo-hero-3d-gallery-backplate.jpg');background-position:center;background-size:cover;border-color:#e7f3ff;border-radius:34px;box-shadow:0 28px 68px #102e5540}.neo-hero:after{background:linear-gradient(110deg,transparent 0 45%,#dff5ff29 49%,transparent 52%);background-size:220% 100%;animation:ice-sheen 12s ease-in-out infinite}.neo-copy{max-width:590px}.neo-copy h1{text-shadow:0 4px 22px #071a3599}.neo-copy>p{color:#e7f3ff}.neo-label{border-color:#d5ecff7d;background:#d9eff41f;box-shadow:inset 0 1px #fff9}.neo-search input{background:#fcfeff;border-color:#cbe0f4;color:#102746;box-shadow:0 9px 18px #081f3a42}.neo-search .database-link{border-color:#cce8ff85;background:#d6eff31c;color:#f7fcff;backdrop-filter:blur(10px)}.neo-search .database-link:hover{background:#d6eff336}.neo-microcopy{color:#cee8fb}.neo-scene{display:none}.neo-route{border-color:#d7e4ef;background:#fbfdff;box-shadow:0 15px 30px #183f6512}.neo-route:first-child{background:linear-gradient(135deg,#fff,#e9f4ff)}.neo-route:last-child{background:linear-gradient(135deg,#fff,#e4eef8)}.neo-route:hover{box-shadow:0 25px 42px #183f6525}.neo-route span,.neo-section-label{color:#28669e}.neo-route b{color:#1d568e}.neo-category-section{border-color:#d7e3ee}.neo-category-grid a{border-color:#d5e2ee;box-shadow:0 10px 19px #183f650c}.neo-category-grid li:nth-child(3n+1) a{background:linear-gradient(145deg,#fff,#e5f2ff)}.neo-category-grid li:nth-child(3n+2) a{background:linear-gradient(145deg,#fff,#edf4fb)}.neo-category-grid li:nth-child(3n) a{background:linear-gradient(145deg,#fff,#dceaf6)}.neo-category-grid a:hover{box-shadow:0 22px 30px #183f6520}.neo-category-grid span,.neo-category-grid em{color:#24619b}.neo-reading{background:linear-gradient(112deg,#dbeaf8,#f7fbff 52%,#d6e6f4)}.neo-reading-list a{border-color:#d6e2ee;background:#fbfdffcc;box-shadow:0 12px 24px #183f650c}.neo-reading-list a:hover{box-shadow:0 22px 34px #183f651f}.neo-reading-list span,.neo-reading-list b{color:#24619b}.neo-close{background:linear-gradient(125deg,#0b2444,#174b7d 58%,#548fc4);box-shadow:0 20px 35px #1538572b}.neo-close p{color:#dbeeff}.neo-close .button{background:#f7fbff;color:#173e68}.neo-close .button:hover{background:#d3e9fb;color:#0e3158}.neo-process{background:linear-gradient(180deg,#f9fcff,#e5eff8)}.neo-process-grid article{border-color:#d7e3ee;background:linear-gradient(145deg,#fff,#e8f2fb);box-shadow:0 13px 27px #183f650c}.neo-process-grid article:nth-child(2){background:linear-gradient(145deg,#fff,#f0f6fc)}.neo-process-grid article:nth-child(3){background:linear-gradient(145deg,#fff,#dcebf7)}.neo-process-grid span{background:#d9eafa;color:#22588e}@keyframes ice-sheen{50%{background-position:100% 0}}@media(prefers-reduced-motion:reduce){.neo-hero:after{animation:none}}@media(max-width:900px){.neo-hero{background-position:61% center}}@media(max-width:760px){.neo-hero{min-height:600px;background-image:linear-gradient(180deg,rgba(8,27,53,.98) 0%,rgba(12,39,73,.94) 47%,rgba(17,54,94,.25) 100%),url('/assets/joyagoo-hero-second-composition.jpg');background-position:64% center}.neo-route h2{font-size:2.45rem}.neo-close{background:linear-gradient(130deg,#0b2444,#194d7f 58%,#5792c7)}}`;
const floatingProductOverride=`.neo-hero{isolation:isolate}.motion-products{position:absolute;z-index:2;inset:0;pointer-events:none;overflow:hidden}.motion-product{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;pointer-events:none;filter:drop-shadow(0 16px 13px #07182b3a);will-change:transform}.motion-coat{clip-path:polygon(59% 11%,64% 11%,67% 16%,69% 23%,72% 31%,70% 43%,73% 62%,70% 70%,63% 71%,57% 68%,51% 65%,50% 60%,53% 52%,52% 43%,52% 34%,54% 24%,56% 16%);animation:motion-coat 7.6s ease-in-out infinite}.motion-bag{clip-path:polygon(82% 20%,88% 20%,92% 27%,94% 40%,94% 57%,91% 66%,84% 70%,78% 63%,75% 54%,75% 39%,77% 28%);animation:motion-bag 6.8s ease-in-out infinite}.motion-sneaker{clip-path:polygon(79% 59%,85% 60%,91% 66%,94% 74%,91% 83%,84% 86%,77% 80%,72% 74%,71% 68%,74% 63%);animation:motion-sneaker 7.2s ease-in-out infinite}.neo-copy{z-index:3}.neo-hero:after{z-index:1}.neo-route-deck,.neo-category-section,.neo-reading,.neo-close,.neo-process{position:relative}@keyframes motion-coat{0%,100%{transform:translate3d(0,0,0) rotate(-.3deg)}50%{transform:translate3d(-4px,-13px,0) rotate(.5deg)}}@keyframes motion-bag{0%,100%{transform:translate3d(0,0,0) rotate(.4deg)}50%{transform:translate3d(6px,-10px,0) rotate(-.6deg)}}@keyframes motion-sneaker{0%,100%{transform:translate3d(0,0,0) rotate(-.4deg)}50%{transform:translate3d(-8px,-9px,0) rotate(.7deg)}}@media(max-width:760px){.motion-products{display:none!important}}@media(prefers-reduced-motion:reduce){.motion-product{animation:none!important}}`;
const localePageCopy={
de:{product:'Produktdaten werden hier als Prüfliste gelesen: Variante, Maße, Material, Bilder und die eine QC-Frage, die die Entscheidung ändern würde.',item:'Vergleiche die ausgewählte Variante, sichtbare Verarbeitung und Maße mit dem Eintrag, bevor du zur Datenbank wechselst.',check:'Prüfe die Größe, die sichtbare Ausführung, die Vollständigkeit und die Produktfotos.',category:'Diese Kategorie bleibt übersichtlich, wenn Auswahl und QC-Frage zusammen dokumentiert werden.',evidence:'Vergleiche nur die gewählte Variante mit dem Angebot und den Lagerbildern. Sichere Fotos und Maße vor dem internationalen Versand.',next:'Wenn die Kategorie klar ist, öffne die passende FindSpreadsheet-Kategorie. Für den Bestellablauf nutze zuerst den QC-Leitfaden.',guide:'Plattformfakten und unabhängige Entscheidungshilfe',platform:'Nutze den offiziellen Dienst für Konto, Zahlung, Bestellstatus, Lager, Paketeinreichung und Versandwahl.',independent:'Nutze diese Seite, um Variante und QC-Prüfpunkte festzuhalten, bevor du den Live-Datensatz öffnest.',articleIntro:'Diese Recherche trennt Produktwahl, Lagerprüfung, Rückgabeentscheidung und Versand in nachvollziehbare Schritte.',articleWarehouse:'Lagerfotos sind ein Entscheidungsnachweis, keine Vollständigkeits- oder Echtheitsgarantie. Prüfe die gewählte Variante und sichtbare Merkmale zeitnah.',articleFreight:'Internationale Kosten hängen von Ziel, Produktart, Gewicht, Packmaß und Route ab. Plane mit einer konservativen Schätzung und bestätige den Betrag erst im Paketformular.',articleTracking:'Tracking ist eine Folge von Übergaben. Notiere Paketnummer und datierte Ereignisse und frage den Support mit einem klaren, belegten Anliegen.',faqTitle:'Praktische Fragen zum Einkauf, klar beantwortet',faqIntro:'Diese unabhängige FAQ fasst öffentlich beschriebene Abläufe zusammen. Regeln, Gebühren und Routen können sich ändern; prüfe vor der Zahlung den aktuellen Bestell- oder Paketbereich.',faqLabel:'Frage',topics:['Unabhängiger Leitfaden','Bestellablauf','Lagerprüfung','QC-Fotos','Rückgabezeitraum','Lagerung','Versandkosten','Tracking und Zoll'],answers:['Diese Seite ist ein unabhängiger Rechercheleitfaden. Kontoaktionen, Zahlungen und Versandentscheidungen erfolgen im jeweiligen Live-Dienst.','Halte Produktlink, Variante, Menge, Bilder und Status zusammen fest. So wird aus einer allgemeinen Frage eine prüfbare Entscheidung.','Lagerbilder helfen bei sichtbaren Merkmalen und der gewählten Variante. Sie ersetzen keine Garantie für verborgene Details oder den Transportzustand.','Für Rückgabe, Versand und Tracking zählen die aktuellen Angaben im Konto und im Paketformular. Frage gezielt mit Bestell- oder Paketnummer und einem datierten Nachweis.']},
fr:{product:'Cette page transforme une fiche produit en checklist : variante, mesures, matière, photos et question QC utile.',item:'Comparez la variante choisie, les finitions visibles et les mesures avant d’ouvrir la base.',check:'Vérifiez la taille, l’aspect visible, les éléments inclus et les photos produit.',category:'Cette catégorie reste claire lorsque le choix et la question QC sont consignés ensemble.',evidence:'Comparez uniquement la variante choisie avec la fiche et les photos d’entrepôt. Gardez photos et mesures avant l’envoi international.',next:'Lorsque la catégorie est claire, ouvrez la catégorie FindSpreadsheet correspondante. Consultez d’abord le guide QC pour le processus.',guide:'Faits de plateforme et conseil indépendant',platform:'Utilisez le service officiel pour le compte, le paiement, le statut, l’entrepôt, le colis et le choix de livraison.',independent:'Utilisez cette page pour noter la variante et les vérifications QC avant d’ouvrir la fiche active.',articleIntro:'Cette recherche sépare le choix produit, le contrôle d’entrepôt, la décision de retour et l’expédition en étapes vérifiables.',articleWarehouse:'Les photos d’entrepôt sont une preuve de décision, pas une garantie complète. Vérifiez rapidement la variante et les détails visibles.',articleFreight:'Le coût international dépend de la destination, du type de produit, du poids, du volume et de la ligne. Planifiez de façon prudente puis confirmez le montant dans le formulaire colis.',articleTracking:'Le suivi est une suite de transmissions. Gardez le numéro et les événements datés, puis posez une question précise au support.',faqTitle:'Questions d’achat pratiques, réponses claires',faqIntro:'Cette FAQ indépendante résume des étapes publiquement décrites. Les règles, frais et lignes peuvent évoluer : vérifiez la page de commande ou de colis avant de payer.',faqLabel:'Question',topics:['Guide indépendant','Parcours de commande','Contrôle d’entrepôt','Photos QC','Délai de retour','Stockage','Coût d’expédition','Suivi et douane'],answers:['Cette page est un guide de recherche indépendant. Les actions de compte, paiements et décisions d’expédition se font dans le service actif concerné.','Conservez le lien produit, la variante, la quantité, les photos et le statut ensemble afin de prendre une décision vérifiable.','Les photos d’entrepôt aident à confirmer la variante reçue et les détails visibles ; elles ne garantissent pas les éléments cachés ni le transport futur.','Pour un retour, un envoi ou le suivi, utilisez les données actuelles du compte et du formulaire colis avec une demande précise et datée.']},
es:{product:'Esta página convierte una ficha en una lista de comprobación: variante, medidas, material, fotos y la pregunta QC útil.',item:'Compara la variante elegida, el acabado visible y las medidas antes de abrir la base.',check:'Revisa talla, acabado visible, componentes incluidos y fotos del producto.',category:'Esta categoría es más clara cuando la elección y la pregunta QC se registran juntas.',evidence:'Compara solo la variante elegida con la ficha y las fotos de almacén. Guarda fotos y medidas antes del envío internacional.',next:'Cuando la categoría esté clara, abre la categoría correspondiente de FindSpreadsheet. Consulta primero la guía QC para el proceso.',guide:'Datos de plataforma y consejo independiente',platform:'Usa el servicio oficial para cuenta, pago, estado, almacén, envío de paquete y elección de ruta.',independent:'Usa esta página para anotar la variante y las comprobaciones QC antes de abrir el registro activo.',articleIntro:'Esta investigación separa la elección del producto, la revisión de almacén, la decisión de devolución y el envío en pasos verificables.',articleWarehouse:'Las fotos de almacén son evidencia para decidir, no una garantía total. Revisa pronto la variante y los detalles visibles.',articleFreight:'El coste internacional depende del destino, tipo de producto, peso, volumen y ruta. Planifica de forma conservadora y confirma el importe en el formulario del paquete.',articleTracking:'El seguimiento es una secuencia de entregas entre operadores. Guarda el número y los eventos fechados y consulta al soporte con una pregunta precisa.',faqTitle:'Preguntas de compra prácticas, respondidas con claridad',faqIntro:'Esta FAQ independiente resume procesos descritos públicamente. Las reglas, tarifas y rutas pueden cambiar; revisa la página actual antes de pagar.',faqLabel:'Pregunta',topics:['Guía independiente','Proceso de pedido','Revisión de almacén','Fotos QC','Plazo de devolución','Almacenamiento','Coste de envío','Seguimiento y aduanas'],answers:['Esta página es una guía de investigación independiente. Las acciones de cuenta, pagos y decisiones de envío se realizan en el servicio activo correspondiente.','Guarda enlace, variante, cantidad, fotos y estado juntos para convertir una duda general en una decisión verificable.','Las fotos de almacén ayudan a confirmar la variante y los detalles visibles; no garantizan elementos ocultos ni el estado futuro en tránsito.','Para devoluciones, envío o seguimiento usa la información actual de la cuenta y del formulario de paquete con una consulta concreta y fechada.']},
it:{product:'Questa pagina trasforma una scheda in una checklist: variante, misure, materiale, foto e domanda QC utile.',item:'Confronta la variante scelta, la finitura visibile e le misure prima di aprire il database.',check:'Verifica taglia, aspetto visibile, componenti inclusi e foto del prodotto.',category:'Questa categoria rimane chiara quando scelta e domanda QC vengono annotate insieme.',evidence:'Confronta solo la variante scelta con la scheda e le foto di magazzino. Conserva foto e misure prima della spedizione internazionale.',next:'Quando la categoria è chiara, apri la categoria FindSpreadsheet corrispondente. Consulta prima la guida QC per il processo.',guide:'Fatti della piattaforma e consiglio indipendente',platform:'Usa il servizio ufficiale per account, pagamento, stato, magazzino, invio pacco e scelta della spedizione.',independent:'Usa questa pagina per annotare variante e controlli QC prima di aprire la scheda attiva.',articleIntro:'Questa ricerca separa scelta del prodotto, controllo in magazzino, decisione di reso e spedizione in passaggi verificabili.',articleWarehouse:'Le foto di magazzino sono prove per decidere, non una garanzia completa. Verifica rapidamente variante e dettagli visibili.',articleFreight:'Il costo internazionale dipende da destinazione, tipo di prodotto, peso, volume e linea. Pianifica con prudenza e conferma l’importo nel modulo del pacco.',articleTracking:'Il tracking è una sequenza di passaggi tra vettori. Conserva numero ed eventi datati e contatta l’assistenza con una domanda precisa.',faqTitle:'Domande pratiche per gli acquisti, con risposte chiare',faqIntro:'Questa FAQ indipendente riassume processi descritti pubblicamente. Regole, tariffe e linee possono cambiare: verifica la pagina attuale prima di pagare.',faqLabel:'Domanda',topics:['Guida indipendente','Flusso dell’ordine','Controllo in magazzino','Foto QC','Finestra di reso','Deposito','Costo di spedizione','Tracking e dogana'],answers:['Questa pagina è una guida di ricerca indipendente. Azioni dell’account, pagamenti e decisioni di spedizione avvengono nel relativo servizio attivo.','Conserva link, variante, quantità, foto e stato insieme per trasformare una domanda generica in una decisione verificabile.','Le foto di magazzino aiutano a confermare variante e dettagli visibili; non garantiscono elementi nascosti o condizioni future durante il trasporto.','Per resi, spedizione o tracking usa i dati correnti dell’account e del modulo pacco con una richiesta precisa e datata.']},
pt:{product:'Esta página transforma uma ficha numa lista de verificação: variante, medidas, material, fotos e a pergunta QC útil.',item:'Compare a variante escolhida, o acabamento visível e as medidas antes de abrir a base.',check:'Verifique tamanho, aspeto visível, componentes incluídos e fotos do produto.',category:'Esta categoria fica mais clara quando a escolha e a pergunta QC são registadas juntas.',evidence:'Compare apenas a variante escolhida com a ficha e as fotos de armazém. Guarde fotos e medidas antes do envio internacional.',next:'Quando a categoria estiver clara, abra a categoria FindSpreadsheet correspondente. Consulte primeiro o guia QC para o processo.',guide:'Factos da plataforma e orientação independente',platform:'Use o serviço oficial para conta, pagamento, estado, armazém, envio de encomenda e escolha de transporte.',independent:'Use esta página para anotar a variante e as verificações QC antes de abrir o registo ativo.',articleIntro:'Esta pesquisa separa a escolha do produto, a revisão no armazém, a decisão de devolução e o envio em etapas verificáveis.',articleWarehouse:'As fotos do armazém são evidência para decidir, não uma garantia completa. Reveja rapidamente a variante e os detalhes visíveis.',articleFreight:'O custo internacional depende do destino, tipo de produto, peso, volume e rota. Planeie com prudência e confirme o valor no formulário da encomenda.',articleTracking:'O rastreio é uma sequência de entregas entre operadores. Guarde o número e os eventos datados e contacte o apoio com uma pergunta precisa.',faqTitle:'Perguntas práticas de compra, respondidas com clareza',faqIntro:'Esta FAQ independente resume processos descritos publicamente. Regras, taxas e rotas podem mudar; confirme a página atual antes de pagar.',faqLabel:'Pergunta',topics:['Guia independente','Fluxo do pedido','Revisão de armazém','Fotos QC','Prazo de devolução','Armazenamento','Custo de envio','Rastreio e alfândega'],answers:['Esta página é um guia de pesquisa independente. Ações de conta, pagamentos e decisões de envio decorrem no respetivo serviço ativo.','Guarde link, variante, quantidade, fotos e estado juntos para transformar uma dúvida geral numa decisão verificável.','As fotos de armazém ajudam a confirmar a variante e detalhes visíveis; não garantem elementos ocultos nem a condição futura em trânsito.','Para devoluções, envio ou rastreio utilize a informação atual da conta e do formulário da encomenda com um pedido concreto e datado.']},
nl:{product:'Deze pagina maakt van een listing een controlelijst: variant, maten, materiaal, foto’s en de QC-vraag die ertoe doet.',item:'Vergelijk de gekozen variant, zichtbare afwerking en maten voordat je de database opent.',check:'Controleer maat, zichtbare afwerking, meegeleverde onderdelen en productfoto’s.',category:'Deze categorie blijft overzichtelijk wanneer keuze en QC-vraag samen worden vastgelegd.',evidence:'Vergelijk alleen de gekozen variant met de listing en magazijnfoto’s. Bewaar foto’s en maten vóór internationale verzending.',next:'Open wanneer de categorie duidelijk is de bijpassende FindSpreadsheet-categorie. Gebruik eerst de QC-gids voor het proces.',guide:'Platformfeiten en onafhankelijk advies',platform:'Gebruik de officiële dienst voor account, betaling, status, magazijn, pakketindiening en verzendkeuze.',independent:'Gebruik deze pagina om variant en QC-controles vast te leggen voordat je het live record opent.',articleIntro:'Dit onderzoek scheidt productkeuze, magazijncontrole, retourbesluit en verzending in verifieerbare stappen.',articleWarehouse:'Magazijnfoto’s zijn bewijs voor een besluit, geen volledige garantie. Controleer variant en zichtbare details snel.',articleFreight:'Internationale kosten hangen af van bestemming, producttype, gewicht, volume en route. Plan voorzichtig en bevestig het bedrag in het pakketformulier.',articleTracking:'Tracking is een reeks overdrachten. Bewaar nummer en gedateerde gebeurtenissen en stel support een gerichte vraag.',faqTitle:'Praktische koopvragen, helder beantwoord',faqIntro:'Deze onafhankelijke FAQ vat openbaar beschreven stappen samen. Regels, kosten en routes kunnen veranderen; controleer de actuele pagina vóór betaling.',faqLabel:'Vraag',topics:['Onafhankelijke gids','Bestelproces','Magazijncontrole','QC-foto’s','Retourtermijn','Opslag','Verzendkosten','Tracking en douane'],answers:['Deze pagina is een onafhankelijke onderzoeksgids. Accountacties, betalingen en verzendbeslissingen gebeuren in de betreffende live dienst.','Bewaar productlink, variant, aantal, foto’s en status samen zodat een algemene vraag een controleerbare beslissing wordt.','Magazijnfoto’s helpen de ontvangen variant en zichtbare details te bevestigen; ze garanderen geen verborgen onderdelen of toekomstige transportconditie.','Gebruik voor retour, verzending of tracking de actuele account- en pakketgegevens met een concrete, gedateerde vraag.']},
pl:{product:'Ta strona zmienia ofertę w listę kontrolną: wariant, wymiary, materiał, zdjęcia i potrzebne pytanie QC.',item:'Porównaj wybrany wariant, widoczne wykończenie i wymiary przed otwarciem bazy.',check:'Sprawdź rozmiar, widoczny stan, dołączone elementy i zdjęcia produktu.',category:'Ta kategoria jest czytelna, gdy wybór i pytanie QC są zapisane razem.',evidence:'Porównuj wyłącznie wybrany wariant z ofertą i zdjęciami magazynowymi. Zachowaj zdjęcia oraz wymiary przed wysyłką międzynarodową.',next:'Gdy kategoria jest jasna, otwórz odpowiednią kategorię FindSpreadsheet. Najpierw użyj przewodnika QC dotyczącego procesu.',guide:'Fakty platformy i niezależne wskazówki',platform:'Korzystaj z oficjalnej usługi do konta, płatności, statusu, magazynu, zgłoszenia paczki i wyboru dostawy.',independent:'Użyj tej strony, aby zapisać wariant i kontrole QC przed otwarciem aktywnego rekordu.',articleIntro:'Ten research oddziela wybór produktu, kontrolę magazynową, decyzję o zwrocie i wysyłkę na weryfikowalne etapy.',articleWarehouse:'Zdjęcia magazynowe są dowodem do decyzji, a nie pełną gwarancją. Szybko sprawdź wariant i widoczne szczegóły.',articleFreight:'Koszt międzynarodowy zależy od kraju, typu produktu, wagi, objętości i trasy. Planuj ostrożnie i potwierdź kwotę w formularzu paczki.',articleTracking:'Śledzenie to sekwencja przekazań. Zachowaj numer i datowane zdarzenia, a do wsparcia kieruj konkretne pytanie.',faqTitle:'Praktyczne pytania zakupowe, jasno wyjaśnione',faqIntro:'To niezależne FAQ podsumowuje publicznie opisane procesy. Zasady, opłaty i trasy mogą się zmieniać; sprawdź aktualną stronę przed płatnością.',faqLabel:'Pytanie',topics:['Niezależny przewodnik','Przebieg zamówienia','Kontrola magazynowa','Zdjęcia QC','Okno zwrotu','Magazynowanie','Koszt wysyłki','Śledzenie i cło'],answers:['Ta strona jest niezależnym przewodnikiem badawczym. Działania na koncie, płatności i decyzje o wysyłce odbywają się w odpowiedniej aktywnej usłudze.','Zapisz link produktu, wariant, ilość, zdjęcia i status razem, aby zmienić ogólne pytanie w sprawdzalną decyzję.','Zdjęcia magazynowe pomagają potwierdzić wariant i widoczne szczegóły; nie gwarantują ukrytych elementów ani przyszłego stanu w transporcie.','W sprawie zwrotu, wysyłki lub śledzenia używaj bieżących danych konta i formularza paczki wraz z konkretnym, datowanym pytaniem.']}
};
